head.script:
        scwin.onpageload = function() {
            windowContainer1.createWindow({
                "title": "Green",
                "src": "scheduleCalendar.xml",
                "windowId": "window1",
                "frameMode": "wframe"
            });
            windowContainer1.createWindow({
                "title": "Blue",
                "src": "scheduleCalendar.xml",
                "windowId": "window2",
                "frameMode": "wframe"
            });
            windowContainer1.createWindow({
                "title": "yellow",
                "src": "scheduleCalendar.xml",
                "windowId": "window3",
                "frameMode": "wframe"
            });
            windowContainer1.createWindow({
                "title": "red",
                "src": "scheduleCalendar.xml",
                "windowId": "window4",
                "frameMode": "wframe"
            });windowContainer1.createWindow({
                "title": "black",
                "src": "scheduleCalendar.xml",
                "windowId": "window5",
                "frameMode": "wframe"
            });

			// HTML 요소의 title 표시(고객사에서 원하는 Tooltip 표시 방법이 아님x)
			$(".w2windowContainer_scrollLeftBtn").attr("title","왼쪽 탭 이동");
			$(".w2windowContainer_scrollRightBtn").attr("title","오른쪽 탭 이동");
			$(".w2windowContainer_controlIcon_windowList").attr("title","탭 목록");
			$(".w2windowContainer_controlIcon_closeAll").attr("title","전체 탭 닫기");
			$(".w2windowContainer_nameLayer_fixOff").attr("title","탭 고정 핀");
        };

        scwin.onpageunload = function() {

        };


	scwin.fireOver = function(node) {
		if (document.createEventObject) {
			node.fireEvent('onmouseover');
		} else if (document.createEvent) {
			window.evt = document.createEvent('MouseEvents');
			evt.initEvent('mouseover', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.onmouseover == 'function') {
			node.onmouseover();
		}
	}
	scwin.mouseOverBehaviour = function(id) {
		window.el = WebSquare.wUnit.getDomById(id);
		scwin.fireOver(el);
	}
	scwin.checkVal1 = function(){
		return WebSquare.wUnit.getDomById('windowContainer1_tooltip').style.display == 'block';
	}
	scwin.checkVal2 = function(){
		return WebSquare.wUnit.getDomById('windowContainer1_right').getAttribute('title') == '오른쪽 탭 이동';
	}	
	scwin.checkVal3 = function(){
		return WebSquare.wUnit.getDomById('windowContainer1_closeAll').getAttribute('title') == '전체 탭 닫기';
	}		
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow3')");
		WebSquare.wUnit.addCommand("pause", "1000");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
